function evidence=f90_xbatt02_extract_evidence(modelPath,outDir)
%F90_XBATT02_EXTRACT_EVIDENCE Run pack scenarios and emit raw facts only.
arguments
    modelPath (1,1) string
    outDir (1,1) string
end
taskRoot=fileparts(mfilename('fullpath'));
projectRoot=fileparts(fileparts(fileparts(fileparts(taskRoot))));
addpath(fullfile(projectRoot,'scripts','formal90'),'-begin');
addpath(fullfile(projectRoot,'scripts','xp9'),'-end');addpath(taskRoot,'-begin');
dependency=fullfile(taskRoot,'f90_xbatt02_measurement.m');
assert(strcmpi(xp9_file_presence_file(dependency), ...
    "present"), ...
    'F90_XBATT02_MEASUREMENT_DEPENDENCY_BINDING');
runScenario=local_handle('run_scenario');measureRun=local_handle('measure_run');
staticAudit=local_handle('static_audit');nominalValues=local_handle('nominal_values');
emptyRun=local_handle('empty_run');emptyRow=local_handle('empty_row');
setBase=local_handle('set_base');snapshotBase=local_handle('snapshot_base');
restoreBase=local_handle('restore_base');
def=f90_xbatt02_definition;inputNames=string({def.public_inputs.name});
snapshot=snapshotBase(inputNames);baseCleanup=onCleanup(@() restoreBase(snapshot)); %#ok<NASGU>
facts=struct('platform_valid',false,'score_inputs_valid',false, ...
    'diagnostics_valid',false,'gate_reasons',strings(0,1), ...
    'static_audit',struct,'scenario_rows',struct([]), ...
    'physical_suite',struct,'causal_pairs',struct);
try
    assert(isfile(modelPath),'F90_XBATT02_MODEL_NOT_FOUND');
    nominal=nominalValues(def);setBase(nominal);[~,model]=fileparts(modelPath);
    model=string(model);load_system(modelPath);
    modelCleanup=onCleanup(@() local_close(model)); %#ok<NASGU>
    audit=staticAudit(model,def);set_param(model,'SimulationCommand','update');
    feval(model,[],[],[],'compile');feval(model,[],[],[],'term');
    scenarioDefs=[struct('id','nominal','values',nominal),def.scenarios];
    runs=repmat(emptyRun(),1,numel(scenarioDefs));rows=repmat(emptyRow(),1,numel(scenarioDefs));
    for index=1:numel(scenarioDefs)
        runs(index)=runScenario(model,scenarioDefs(index),def);
        rows(index)=measureRun(runs(index),def);
    end
    [suite,pairs]=local_suite_facts(rows,def);
    gate=all([rows.valid])&&audit.output_contract_connected&& ...
        audit.precomputed_direct_output_count==0&& ...
        audit.suspicious_callback_count==0&&audit.dynamic_state_evidence;
    reasons=strings(0,1);if ~gate,reasons="GLOBAL_GATE_FAILED";end
    facts.platform_valid=true;facts.score_inputs_valid=gate;
    facts.diagnostics_valid=true;facts.gate_reasons=reasons;
    facts.static_audit=audit;facts.scenario_rows=rows;
    facts.physical_suite=suite;facts.causal_pairs=pairs;
    facts.range_scenario_ids=def.range_scenario_ids;
    facts.dynamic_scenario_ids=def.dynamic_scenario_ids;
    save(fullfile(outDir,'waveforms.mat'),'runs','def','-v7.3');
catch ME
    facts.gate_reasons="Evaluator/platform failure: "+string(ME.message);
    facts.error_identifier=string(ME.identifier);facts.error_message=string(ME.message);
end
evidence=formal90_write_evidence("F90-XBATT-02",modelPath,outDir, ...
    def.groups.weights,facts,dependency);
end

function [suite,pairs]=local_suite_facts(rows,def)
valid=rows([rows.valid]);
suite=struct( ...
    'request_contract_worst',max([valid.request_nrmse]), ...
    'current_closure_worst',max([valid.current_closure_error]), ...
    'voltage_closure_worst',max([valid.voltage_closure_error]), ...
    'pump_auxiliary_closure_worst',max([valid.pump_auxiliary_closure_error]), ...
    'reported_state_worst',max([[valid.reported_min_soc_error], ...
        [valid.reported_max_temperature_error_K]/10]), ...
    'coulomb_balance_worst',max([valid.coulomb_balance_error]), ...
    'per_cell_voltage_spread_worst',max([valid.per_cell_voltage_spread]), ...
    'mixed_geometry_ratio_worst',max([valid.mixed_geometry_ratio_error]), ...
    'polarization_drop_min_V',min([valid.polarization_drop_per_cell_V]), ...
    'heat_current_correlation_min',min([valid.heat_current_correlation]), ...
    'thermal_balance_worst',max([valid.thermal_balance_error]), ...
    'coolant_enthalpy_worst',max([valid.coolant_enthalpy_error]), ...
    'coolant_passivity_worst',max([valid.coolant_passivity_error]), ...
    'pump_thermal_correlation_min',min([valid.pump_thermal_correlation]), ...
    'cooling_path_correlation_min',min([valid.cooling_path_correlation]));
low=local_row(rows,'demand_pair_low');high=local_row(rows,'demand_pair_high');
pairs.demand=struct( ...
    'current_ratio',high.current_rms_A/max(low.current_rms_A,1), ...
    'heat_ratio',high.mean_heat_generation_W/max(low.mean_heat_generation_W,1), ...
    'soc_depletion_ratio',high.soc_depletion/max(low.soc_depletion,1e-4), ...
    'temperature_rise_delta_K',high.temperature_rise_K-low.temperature_rise_K, ...
    'cooling_power_ratio',high.mean_cooling_power_W/max(low.mean_cooling_power_W,1));
low=local_row(rows,'maldistribution_pair_low');high=local_row(rows,'maldistribution_pair_high');
pairs.maldistribution=struct('flow_cv_delta',high.flow_cv_mean-low.flow_cv_mean, ...
    'temperature_spread_delta_K',high.temperature_spread_K-low.temperature_spread_K);
dynamic=rows(ismember(string({rows.id}),def.dynamic_scenario_ids)&[rows.valid]);
pairs.regeneration=struct( ...
    'minimum_negative_current_fraction',min([dynamic.regen_current_fraction]), ...
    'minimum_soc_gain',min([dynamic.regen_soc_gain]), ...
    'minimum_voltage_rise_per_cell_V',min([dynamic.regen_voltage_rise_per_cell_V]));
lowSoc=local_row(rows,'low_soc_supervision');
pairs.low_soc_supervision=struct('minimum_soc',lowSoc.minimum_soc, ...
    'attenuation_fraction',lowSoc.attenuation_fraction, ...
    'limiter_consistency_error',lowSoc.limiter_consistency_error, ...
    'risk_attenuation_correlation',lowSoc.risk_attenuation_correlation, ...
    'risk_attenuation_gain',lowSoc.risk_attenuation_gain, ...
    'post_limit_soc_change',lowSoc.post_limit_soc_change);
pairs.cooling_chain=struct( ...
    'minimum_pump_thermal_correlation',min([dynamic.pump_thermal_correlation]), ...
    'minimum_flow_heat_correlation',min([dynamic.cooling_path_correlation]));
end
function row=local_row(rows,id),row=rows(string({rows.id})==id);end
function h=local_handle(name),h=@(varargin)f90_xbatt02_measurement_compatibility(name,varargin{:});end
function local_close(model),try,if bdIsLoaded(model),close_system(model,0);end,catch,end,end
